export default function JamesTheGreater({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* Stable white paper underneath every paint region. */}
        <rect
          x="0"
          y="0"
          width="1024"
          height="1536"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Open sky and distant landscape base. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1024" height="1536" />
        </g>

        {/* Left and right cloud banks behind the pilgrim saint. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} />
        </g>

        {/* Halo ring plus the halo field behind the head. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} />
        </g>

        {/* Pilgrim cloak / mantle, including the large outer drape and visible sleeves. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} />
        </g>

        {/* Inner tunic / robe body and lower garment. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} />
        </g>

        {/* Face, neck, and both hands. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} />
        </g>

        {/* Hair, curls, moustache, and beard. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} />
        </g>

        {/* Pilgrim staff, strap, satchel, medallion, and belt accessories. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} />
        </g>

        {/* Scallop-shell symbols and the roadside marker. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} />
        </g>

        {/* Exact traced black line art from the supplied James image.
            Keep this last and non-interactive so every region remains paintable. */}
        <path
          {...detail}
          {...ink}
          d={JAMES_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}